mapper.select:
SELECT T.* FROM (SELECT A.*, B.MONITORTMPLGROUP, E.ELNTMPLNAME FROM T_EMC_MONITOR_TMPL A LEFT JOIN T_EMC_MONITOR_TMPL_GROUP B ON A.MONITORTMPLGROUPID = B.ID LEFT JOIN T_CORE_ELN_TMPL E ON A.ELNTMPLID = E.ID) T
AND NOT EXISTS (SELECT 1 FROM ${targetTable} TAR_ WHERE TAR_.${targetMonitorTmplIdColumn} = T.ID
AND TAR_.${targetFilterColumn} = #{targetFilterValue}
AND TAR_.${targetFilterColumn1} = #{targetFilterValue1}
)
AND EXISTS (SELECT 1 FROM T_CORE_USER_PERMISSION UP WHERE UP.PERMISSIONTYPEID = 'T_CORE_ORG' AND UP.TARGETID = T.ORGID AND UP.USERID = #{loginUser.id})
ORDER BY
T.ORDERNO ASC,T.ID DESC
